package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NullArgument() {
        Complex c = new Complex(1.0, 1.0);
        try {
            c.divide(null);
            Assert.fail("Expected NullArgumentException");
        } catch (NullArgumentException e) {
            // Success
        }
    }

    @Test
    public void testDivide_NaN_Result() {
        Complex nan = Complex.NaN;
        Complex c = new Complex(1.0, 1.0);
        Assert.assertTrue("Result should be NaN when dividend is NaN", c.divide(new Complex(1, 1)).isNaN());
        Assert.assertTrue("Result should be NaN when divisor is NaN", nan.divide(new Complex(1, 1)).isNaN());
    }

    @Test
    public void testDivide_DivideByZero() {
        Complex c = new Complex(1.0, 1.0);
        Complex zero = new Complex(0.0, 0.0);
        Assert.assertTrue("Division by zero should return NaN", c.divide(zero).isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_FiniteDividend() {
        Complex c = new Complex(1.0, 1.0);
        Complex infinite = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex result = c.divide(infinite);
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_BranchSmallDenominator_Case1() {
        // Case where |c| < |d|
        // divisor.getReal() = 1, divisor.getImaginary() = 10
        Complex dividend = new Complex(2.0, 4.0);
        Complex divisor = new Complex(1.0, 10.0);

        // Manual calculation: (2+4i)/(1+10i) = [(2+4i)(1-10i)] / [1^2 + 10^2]
        // = (2 - 20i + 4i + 40) / 101 = (42 - 16i) / 101
        // real = 42/101 ≈ 0.4158415841, imag = -16/101 ≈ -0.1584158415

        Complex result = dividend.divide(divisor);
        Assert.assertEquals(42.0 / 101.0, result.getReal(), EPSILON);
        Assert.assertEquals(-16.0 / 101.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_BranchLargeDenominator_Case2() {
        // Case where |c| >= |d|
        // divisor.getReal() = 10, divisor.getImaginary() = 1
        Complex dividend = new Complex(2.0, 4.0);
        Complex divisor = new Complex(10.0, 1.0);

        // Manual calculation: (2+4i)/(10+1i) = [(2+4i)(10-1i)] / [10^2 + 1^2]
        // = (20 - 2i + 40i + 4) / 101 = (24 + 38i) / 101
        // real = 24/101 ≈ 0.2376237624, imag = 38/101 ≈ 0.3762376237

        Complex result = dividend.divide(divisor);
        Assert.assertEquals(24.0 / 101.0, result.getReal(), EPSILON);
        Assert.assertEquals(38.0 / 101.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_BothInfinite() {
        // If both are infinite, it doesn't hit the 'divisor.isInfinite() && !isInfinite()' block
        // It falls through to the math logic.
        Complex dividend = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
        Complex divisor = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
        Complex result = dividend.divide(divisor);
        // Depending on implementation of infinity math, usually results in NaN
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_StandardReal() {
        Complex dividend = new Complex(10.0, 0.0);
        Complex divisor = new Complex(2.0, 0.0);
        Complex result = dividend.divide(divisor);
        Assert.assertEquals(5.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }
}
